create extension if not exists postgis;
create table profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null,avatar_url text,instagram_username text,created_at timestamptz not null default now());
create table interests(id bigint generated always as identity primary key,name text unique not null);
create table user_interests(user_id uuid references profiles(id) on delete cascade,interest_id bigint references interests(id) on delete cascade,primary key(user_id,interest_id));
create table posts(id bigint generated always as identity primary key,user_id uuid not null references profiles(id) on delete cascade,body text,image_url text,interest_id bigint references interests(id),latitude double precision,longitude double precision,location geography(point,4326) generated always as(case when latitude is null or longitude is null then null else st_setsrid(st_makepoint(longitude,latitude),4326)::geography end) stored,created_at timestamptz not null default now());
create table likes(user_id uuid references profiles(id) on delete cascade,post_id bigint references posts(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,post_id));
create table comments(id bigint generated always as identity primary key,post_id bigint references posts(id) on delete cascade,user_id uuid references profiles(id) on delete cascade,body text not null,created_at timestamptz not null default now());
create table blocks(blocker_id uuid references profiles(id) on delete cascade,blocked_id uuid references profiles(id) on delete cascade,primary key(blocker_id,blocked_id));
create table reports(id bigint generated always as identity primary key,reporter_id uuid references profiles(id),post_id bigint references posts(id),reason text not null,created_at timestamptz not null default now());
create index posts_location_gix on posts using gist(location);create index posts_created_idx on posts(created_at desc);
alter table profiles enable row level security;alter table posts enable row level security;alter table likes enable row level security;alter table comments enable row level security;
create policy "profiles readable" on profiles for select using(true);create policy "own profile insert" on profiles for insert with check(auth.uid()=id);create policy "posts readable" on posts for select using(true);create policy "own posts insert" on posts for insert with check(auth.uid()=user_id);create policy "own posts delete" on posts for delete using(auth.uid()=user_id);create policy "likes readable" on likes for select using(true);create policy "own likes insert" on likes for insert with check(auth.uid()=user_id);create policy "own likes delete" on likes for delete using(auth.uid()=user_id);create policy "comments readable" on comments for select using(true);create policy "own comments" on comments for insert with check(auth.uid()=user_id);
create or replace function nearby_feed(lat double precision,lng double precision,radius_m integer default 20000) returns table(id bigint,body text,image_url text,created_at timestamptz,distance_m double precision,profiles jsonb,interests jsonb) language sql stable security invoker as $$ select p.id,p.body,p.image_url,p.created_at,case when p.location is null then null else st_distance(p.location,st_setsrid(st_makepoint(lng,lat),4326)::geography) end,jsonb_build_object('username',pr.username,'avatar_url',pr.avatar_url,'instagram_username',pr.instagram_username),case when i.id is null then null else jsonb_build_object('name',i.name) end from posts p join profiles pr on pr.id=p.user_id left join interests i on i.id=p.interest_id where p.location is null or st_dwithin(p.location,st_setsrid(st_makepoint(lng,lat),4326)::geography,radius_m) order by p.created_at desc limit 100; $$;
